    ("facility-management", "Facility Management", "AI Workflow: AI Facility Operations", "Operations", "Optimize facility operations with AI-powered maintenance scheduling, energy management, and space utilization.", ["Connect building systems to AI platform", "AI monitors equipment health and energy usage", "Schedule predictive maintenance", "Optimize space utilization"], ["Zapier", "Datadog", "ChatGPT"], [("How does AI improve facility management?", "AI predicts equipment failures before they occur, optimizes energy consumption, and analyzes space utilization to improve workplace efficiency."), ("Can AI reduce energy costs?", "AI-optimized building systems typically reduce energy costs by 15-25% through smart HVAC scheduling, lighting control, and demand management."), ("How does predictive maintenance work?", "AI analyzes equipment sensor data to identify patterns that precede failures, scheduling maintenance before breakdowns occur and reducing downtime by 30-50%.")]),
    ("supply-chain-monitoring", "Supply Chain Monitoring", "AI Workflow: AI Supply Chain Intelligence", "Operations", "Monitor supply chain health with AI-powered risk detection, lead time prediction, and disruption alerting.", ["Connect supplier and logistics data", "AI monitors supply chain performance", "Predict lead time delays and risks", "Alert on potential disruptions"], ["Zapier", "ChatGPT", "Datadog"], [("How does AI monitor supply chains?", "AI tracks supplier performance, shipping times, inventory levels, and external risk factors to provide real-time visibility across your supply chain."), ("Can AI predict supply chain disruptions?", "AI analyzes weather, geopolitical events, supplier financial health, and logistics data to predict disruptions 2-4 weeks before impact."), ("How does AI improve supplier reliability?", "AI scores suppliers on delivery performance, quality metrics, and risk factors, helping procurement teams make data-driven sourcing decisions.")]),
